/**
 * n8n Code Node
 * Mode: Run Once for All Items
 * Purpose: Clean and parse AI-generated student data
 */

const inputItems = $input.all();

// Convert invalid or placeholder values to null
function cleanValue(value) {
    if (value === null || value === undefined) {
        return null;
    }

    if (typeof value === "string") {
        const cleaned = value.trim();

        const invalidValues = [
            "",
            "MISSING",
            "INVALID",
            "INVALID_EMAIL",
            "UNKNOWN",
            "NULL",
            "N/A",
            "NONE",
            "NOT PROVIDED",
            "UNDEFINED"
        ];

        if (invalidValues.includes(cleaned.toUpperCase())) {
            return null;
        }

        return cleaned;
    }

    return value;
}

// Validate email
function validateEmail(email) {
    const value = cleanValue(email);

    if (!value) return null;

    const emailRegex =
        /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    return emailRegex.test(value)
        ? value.toLowerCase()
        : null;
}

// Validate phone number
function validatePhone(phone) {
    const value = cleanValue(phone);

    if (!value) return null;

    const digits = String(value).replace(/\D/g, "");

    // Accept 10-digit Indian mobile numbers
    // or numbers with an international country code
    if (digits.length === 10) {
        return digits;
    }

    if (digits.length >= 11 && digits.length <= 15) {
        return "+" + digits;
    }

    return null;
}

// Validate date (YYYY-MM-DD)
function validateDate(date) {
    const value = cleanValue(date);

    if (!value) return null;

    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
        return null;
    }

    const parsed = new Date(value + "T00:00:00Z");

    return !isNaN(parsed.getTime()) &&
        parsed.toISOString().slice(0, 10) === value
        ? value
        : null;
}

// Convert AI output into JSON
function parseAIOutput(raw) {
    if (typeof raw === "object" && raw !== null) {
        return raw;
    }

    let text = String(raw ?? "").trim();

    // Remove Markdown code fences
    text = text
        .replace(/^```json\s*/i, "")
        .replace(/^```\s*/, "")
        .replace(/\s*```$/, "")
        .trim();

    // Extract JSON from surrounding text
    const firstObject = text.indexOf("{");
    const firstArray = text.indexOf("[");

    let start;

    if (firstObject === -1) start = firstArray;
    else if (firstArray === -1) start = firstObject;
    else start = Math.min(firstObject, firstArray);

    if (start > 0) {
        text = text.slice(start);
    }

    return JSON.parse(text);
}

const results = [];

for (let i = 0; i < inputItems.length; i++) {

    try {
        const item = inputItems[i].json;

        // Change this field name if your AI Agent uses
        // another output property
        const rawOutput =
            item.output ??
            item.text ??
            item.response ??
            item;

        let parsed = parseAIOutput(rawOutput);

        // Support both single records and arrays
        const records = Array.isArray(parsed)
            ? parsed
            : [parsed];

        for (const record of records) {

            results.push({
                json: {
                    Name: cleanValue(record.Name),
                    Email: validateEmail(record.Email),
                    Phone: validatePhone(record.Phone),
                    Course: cleanValue(record.Course),
                    Fee_Paid:
                        typeof record.Fee_Paid === "boolean"
                            ? record.Fee_Paid
                            : String(record.Fee_Paid).toLowerCase() === "true"
                                ? true
                                : String(record.Fee_Paid).toLowerCase() === "false"
                                    ? false
                                    : null,
                    City: cleanValue(record.City),
                    Enrolled_Date: validateDate(record.Enrolled_Date),
                    Data_Status: "Cleaned"
                }
            });
        }

    } catch (error) {

        results.push({
            json: {
                Data_Status: "Error",
                Error_Message: error.message,
                Original_Data: inputItems[i].json
            }
        });
    }
}

return results;
